B.bbM=new A.a0("tortilla-francesa","Tortilla francesa",5,"1 raci\xf3n",B.azQ,B.awE,null,300,23,B.F,B.dG,!1)
B.aKW=s(["1-2 hamburguesas de ternera","1 pan de hamburguesa o 2 rebanadas","1 loncha de queso","Tomate frito o tu salsa","1 patata mediana","1 cucharadita de aceite de oliva","Sal"],t.s)
