B.bc5=new A.a0("hamburguesa","Hamburguesa casera con queso y patatas al horno",35,"1 raci\xf3n",B.aKW,B.asO,null,750,37,B.F,B.dF,!1)
B.amt=s(["1-2 tortillas de wrap","120 g de pollo en tiras","1 loncha de queso","2 cucharadas de ma\xedz","\xbc de pepino en tiras","1 cucharadita de aceite, sal y piment\xf3n"],t.s)
B.aIY=s(["Saltea el pollo con aceite, sal y piment\xf3n 6-7 minutos.","Calienta la tortilla 20 segundos en una sart\xe9n.","Rell\xe9nala con el pollo, el queso, el ma\xedz y el pepino.","Enr\xf3llala doblando primero los extremos."],t.s)
B.bdP=new A.a0("wrap-pollo","Wrap de pollo con queso, ma\xedz y pepino",15,"1 raci\xf3n",B.amt,B.aIY,"Envuelto en papel de aluminio sirve para llevar.",530,35,B.F,B.ib,!1)
B.aqs=s(["200 g de arroz","200 g de pollo troceado","100 g de lomo o costilla de cerdo","100 g de jud\xedas verdes","2 cucharadas de tomate frito","800 ml de agua o caldo","Aceite, sal, piment\xf3n","Colorante o azafr\xe1n"],t.s)
B.arH=s(["Dora la carne en la paellera con aceite y sal, 8 minutos.","A\xf1ade las jud\xedas y rehoga 3 minutos.","A\xf1ade el tomate y el piment\xf3n y remueve 1 minuto.","Echa el agua caliente y el colorante y deja que hierva.","Reparte el arroz: 10 minutos a fuego fuerte y 8 a fuego suave, sin remover.","Deja reposar 5 minutos tapada con un trapo."],t.s)
B.be6=new A.a0("paella",u.gs,45,"2 raciones",B.aqs,B.arH,"La segunda raci\xf3n, a un t\xe1per para otro d\xeda o al congelador.",720,35,B.F,B.cL,!1)
