B.bdw=new A.a0("gambas-ajillo","Gambas al ajillo con pan",10,"1 raci\xf3n",B.aqM,B.asP,null,670,39,B.F,B.fZ,!1)
B.aMm=s(["350 g de at\xfan fresco o congelado en dados","3 cebollas","2 dientes de ajo","1 hoja de laurel","\xbd vaso de vino blanco o caldo","Aceite y sal","Patatas o arroz para acompa\xf1ar"],t.s)
