B.aSx=s(["Jam\xf3n york \u2192 gambas o pollo.","Guisantes y zanahoria \u2192 ma\xedz y pimiento."],t.s)
B.b8J=new A.aa(B.t,B.P_,"Mejor con arroz cocido el d\xeda anterior y fr\xedo: queda suelto. Si lo haces en el momento, exti\xe9ndelo en un plato para que se enfr\xede.","El arroz est\xe1 caliente, suelto y algo tostado; todo bien repartido.",B.av5,B.atQ,B.aSx,"2 d\xedas en la nevera.",null,B.q)
B.axT=s(["Sart\xe9n grande","Esp\xe1tula ancha"],t.s)
